"use client";

import { forwardRef, type ComponentProps } from "react";
import LegacyRecommendationCard from "../beautiful-ui/primitives/RecommendationCard";
import { BeautifulUIRoot } from "../beautiful-ui/BeautifulUIRoot";

export type RecommendationCardProps = NonNullable<ComponentProps<typeof LegacyRecommendationCard>>;

export const RecommendationCard = forwardRef<HTMLDivElement, RecommendationCardProps>(
  (props, ref) => (
    <BeautifulUIRoot ref={ref}>
      <LegacyRecommendationCard {...props} />
    </BeautifulUIRoot>
  ),
);

RecommendationCard.displayName = "RecommendationCard";

export default RecommendationCard;

"use client";

import { useId, useRef, useState } from "react";
import { AnimatePresence, motion, useIsPresent } from "framer-motion";
import { FluidHoverHighlight } from "@/components/ui/fluid-hover-highlight";
import {
  useFluidHover,
  useRegisterFluidHoverItem,
  type UseFluidHoverReturn,
} from "@/hooks/use-fluid-hover";
import { springs } from "@/lib/springs";
import { useShape } from "@/lib/shape-context";
import { cn } from "@/lib/utils";
import { Button, type ButtonVariant } from "../atoms/Button";
import { useReducedMotion } from "../hooks/useReducedMotion";
import "../beautiful-ui.css";

type Option = {
  key: string;
  body: React.ReactNode;
  short: string;
  signal: number;
  tone: string;
  label: string;
  cta: string;
  ctaVariant: ButtonVariant;
};

function VendorChip({ name, color = "var(--orange)" }: { name: string; color?: string }) {
  const shape = useShape();
  return (
    <span
      className={cn(
        "mx-0.5 inline-flex items-center gap-1 bg-[var(--field)] py-px pl-[3px] pr-1.5 align-middle",
        shape.item,
      )}
    >
      <span
        className="flex size-4 shrink-0 items-center justify-center rounded-full text-[11px] font-semibold leading-none text-[var(--background)]"
        style={{ background: color }}
      >
        {name.charAt(0)}
      </span>
      <span className="text-[12px] font-medium text-[var(--ink)]">{name}</span>
    </span>
  );
}

function Pill({
  children,
  tone = "neutral",
}: {
  children: React.ReactNode;
  tone?: "neutral" | "green";
}) {
  const shape = useShape();
  return (
    <span
      className={`mx-0.5 inline-flex items-center ${shape.item} px-1.5 py-0 align-middle text-[12px] font-medium ${
        tone === "green"
          ? "bg-[var(--green-tint)] text-[var(--green)]"
          : "bg-[var(--field)] text-[var(--ink-2)]"
      }`}
      style={{
        boxShadow:
          tone === "green"
            ? "0 0 0 1px color-mix(in oklab, var(--green) 12%, transparent)"
            : "0 0 0 1px color-mix(in oklab, var(--border) 40%, transparent)",
      }}
    >
      {children}
    </span>
  );
}

const OPTIONS: Option[] = [
  {
    key: "high",
    body: (
      <>
        Reorder waffle cones from <VendorChip name="Cone King" /> with lead time{" "}
        <Pill tone="green">7 days</Pill>
      </>
    ),
    short: "Reorder from Cone King · 7-day lead",
    signal: 3,
    tone: "var(--green)",
    label: "High confidence",
    cta: "Accept",
    ctaVariant: "accent",
  },
  {
    key: "review",
    body: (
      <>
        Switch vanilla to <Pill>Vanilla Madagascar</Pill> for peak season.
      </>
    ),
    short: "Switch to Vanilla Madagascar",
    signal: 2,
    tone: "var(--orange)",
    label: "Needs review",
    cta: "Configure",
    ctaVariant: "primary",
  },
  {
    key: "none",
    body: (
      <>
        Fall back to a <span className="font-medium text-[var(--ink)]">full restock</span> across
        every SKU.
      </>
    ),
    short: "Full restock across every SKU",
    signal: 0,
    tone: "var(--ink-3)",
    label: "No signal",
    cta: "Accept full restock",
    ctaVariant: "primary",
  },
];

function Meter({ signal, tone }: { signal: number; tone: string }) {
  return (
    <span className="flex items-end gap-0.5" aria-hidden="true">
      {[0, 1, 2].map((bar) => (
        <span
          key={bar}
          className="w-1 rounded-full transition-colors duration-240"
          style={{ height: 10, background: bar < signal ? tone : "var(--line-strong)" }}
        />
      ))}
    </span>
  );
}

function AlternativeRow({
  option,
  index,
  hover,
  onSelect,
}: {
  option: Option;
  index: number;
  hover: UseFluidHoverReturn;
  onSelect: () => void;
}) {
  const shape = useShape();
  const ref = useRef<HTMLButtonElement>(null);
  useRegisterFluidHoverItem(hover.registerItem, index, ref);

  return (
    <button
      ref={ref}
      data-alternative-index={index}
      type="button"
      onClick={onSelect}
      onFocus={() => hover.setActiveIndex(index)}
      className={cn(
        "relative z-10 flex min-h-8 w-full items-center gap-2.5 px-2 py-1.5 text-left transition-transform duration-80 active:scale-[0.98]",
        shape.item,
      )}
    >
      <Meter signal={option.signal} tone={option.tone} />
      <span className="min-w-0 flex-1 truncate text-[13px] text-[var(--ink)]">{option.short}</span>
      <span className="shrink-0 text-[11px] text-[var(--ink-3)]">{option.label}</span>
    </button>
  );
}

function AlternativesList({
  options,
  onSelect,
}: {
  options: { option: Option; index: number }[];
  onSelect: (index: number, optionKey: string) => void;
}) {
  const shape = useShape();
  const ref = useRef<HTMLDivElement>(null);
  const mouseInside = useRef(false);
  const hover = useFluidHover(ref, { gapClick: false });
  const isPresent = useIsPresent();

  return (
    <div
      ref={ref}
      className="relative px-3 py-3"
      {...hover.handlers}
      onMouseEnter={() => {
        mouseInside.current = true;
        hover.handlers.onMouseEnter();
      }}
      onMouseLeave={() => {
        mouseInside.current = false;
        hover.handlers.onMouseLeave();
        const focused = document.activeElement;
        if (
          focused instanceof HTMLElement &&
          ref.current?.contains(focused) &&
          focused.matches(":focus-visible")
        ) {
          const index = focused.getAttribute("data-alternative-index");
          if (index !== null) hover.setActiveIndex(Number(index));
        }
      }}
      onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget) && !mouseInside.current) {
          hover.setActiveIndex(null);
        }
      }}
    >
      <p className="relative z-10 px-1 pb-1 text-[11px] font-medium text-[var(--ink-3)]">
        Other options
      </p>
      <FluidHoverHighlight hover={hover} hidden={!isPresent} className={shape.bg} />
      {options.map(({ option, index }, rowIndex) => (
        <AlternativeRow
          key={option.key}
          option={option}
          index={rowIndex}
          hover={hover}
          onSelect={() => onSelect(index, option.key)}
        />
      ))}
    </div>
  );
}

export interface RecommendationCardProps {
  onAccept?: (optionKey: string) => void;
  onAlternativesChange?: (open: boolean) => void;
  onSelectionChange?: (optionKey: string) => void;
}

export default function RecommendationCard({
  onAccept,
  onAlternativesChange,
  onSelectionChange,
}: RecommendationCardProps = {}) {
  const shape = useShape();
  const reducedMotion = useReducedMotion();
  const drawerId = useId();
  const [selected, setSelected] = useState(0);
  const [open, setOpen] = useState(false);
  const [drawerSession, setDrawerSession] = useState(0);
  const [accepted, setAccepted] = useState(false);

  const active = OPTIONS[selected];
  const others = OPTIONS.map((option, index) => ({ option, index })).filter(
    ({ index }) => index !== selected,
  );

  const setDrawerOpen = (next: boolean) => {
    if (next) setDrawerSession((session) => session + 1);
    setOpen(next);
    onAlternativesChange?.(next);
  };

  const accept = () => {
    if (accepted) return;
    setAccepted(true);
    onAccept?.(active.key);
  };

  return (
    <div
      className={cn(
        "w-full max-w-95 overflow-hidden bg-[var(--surface)] shadow-surface-2",
        shape.container,
      )}
    >
      <div className="primitive-card-pad">
        <span className="text-[16px] font-semibold leading-snug text-[var(--ink)]">
          Want me to place this restock order?
        </span>
        <p
          key={active.key}
          className="mt-1.5 min-h-12 text-[13px] leading-relaxed text-[var(--ink-2)]"
          style={{ animation: reducedMotion ? undefined : "fade-in 160ms ease-out both" }}
        >
          {active.body}
        </p>
      </div>

      <AnimatePresence initial={false}>
        {open ? (
          <motion.div
            id={drawerId}
            initial={reducedMotion ? false : { height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={reducedMotion ? { duration: 0 } : springs.slow}
            className="overflow-hidden border-t border-border/40 bg-[var(--surface)]"
          >
            <AlternativesList
              // Reset measurements and hover for each option set and drawer opening.
              key={`${active.key}-${drawerSession}`}
              options={others}
              onSelect={(index, optionKey) => {
                setSelected(index);
                setAccepted(false);
                onSelectionChange?.(optionKey);
              }}
            />
          </motion.div>
        ) : null}
      </AnimatePresence>

      <div className="primitive-card-footer flex items-center justify-between gap-3 bg-[var(--surface)]">
        <span className="flex items-center gap-2">
          <Meter signal={active.signal} tone={active.tone} />
          <span className="text-[13px] font-medium text-[var(--ink-2)]">{active.label}</span>
        </span>

        <span className="-mr-0.5 flex items-center gap-2">
          <Button
            type="button"
            variant="secondary"
            size="sm"
            aria-expanded={open}
            aria-controls={drawerId}
            onClick={() => setDrawerOpen(!open)}
            className="px-2.5 text-[13px] focus-visible:!outline-none"
          >
            Alternatives
          </Button>
          <Button
            type="button"
            variant={accepted ? "success" : active.ctaVariant}
            size="sm"
            onClick={accept}
            className="text-[13px] focus-visible:!outline-none"
          >
            {accepted ? "Accepted" : active.cta}
          </Button>
        </span>
      </div>

      <span role="status" aria-live="polite" className="sr-only">
        {accepted ? `${active.short} accepted` : `${active.label}: ${active.short}`}
      </span>
    </div>
  );
}

"use client";

import "./beautiful-ui.css";
import { forwardRef, type CSSProperties, type HTMLAttributes } from "react";
import { SurfaceProvider, useSurface } from "@/lib/surface-context";
import { useShapeVariant } from "@/lib/shape-context";

export type BeautifulUIRootProps = HTMLAttributes<HTMLDivElement>;

type AdapterStyle = CSSProperties & Record<`--${string}`, string | number>;

function clampSurface(level: number) {
  return Math.max(1, Math.min(8, level));
}

function createAdapterStyle(
  substrate: number,
  surface: number,
  style?: CSSProperties,
): AdapterStyle {
  const inset = clampSurface(substrate + 1);
  const overlay = clampSurface(surface + 2);
  const raisedOverlay = clampSurface(surface + 4);

  return {
    "--page": `var(--surface-${substrate})`,
    "--canvas": `var(--surface-${substrate})`,
    "--surface": `var(--surface-${surface})`,
    "--inset": `var(--surface-${inset})`,
    "--tooltip-bg": `var(--surface-${overlay})`,
    "--overlay-surface": `var(--surface-${overlay})`,
    "--overlay-raised": `var(--surface-${raisedOverlay})`,
    ...style,
  };
}

function useBeautifulUIScope(offset = 2) {
  const substrate = useSurface();
  const surface = clampSurface(substrate + offset);
  const shape = useShapeVariant();

  return {
    shape,
    substrate,
    surface,
    style: createAdapterStyle(substrate, surface),
  };
}

/**
 * Internal compatibility boundary for the adapted primitives. It has no layout
 * box of its own: public components use it internally so consumers inherit the
 * active BoringUI theme, surface level, and radius mode without a wrapper.
 */
export const BeautifulUIRoot = forwardRef<HTMLDivElement, BeautifulUIRootProps>(
  ({ className, style, ...props }, ref) => {
    const scope = useBeautifulUIScope();

    return (
      <SurfaceProvider value={scope.surface}>
        <div
          ref={ref}
          data-bui-component=""
          data-shape={scope.shape}
          data-surface={scope.surface}
          className={["beautiful-ui", "contents", className].filter(Boolean).join(" ")}
          style={{ ...scope.style, ...style }}
          {...props}
        />
      </SurfaceProvider>
    );
  },
);

BeautifulUIRoot.displayName = "BeautifulUIRoot";

/** Applies the same BoringUI scope to content rendered in a body portal. */
export const BeautifulUIPortalRoot = forwardRef<HTMLDivElement, BeautifulUIRootProps>(
  ({ className, style, ...props }, ref) => {
    const scope = useBeautifulUIScope();

    return (
      <SurfaceProvider value={scope.surface}>
        <div
          ref={ref}
          data-bui-component=""
          data-shape={scope.shape}
          data-surface={scope.surface}
          className={["beautiful-ui", className].filter(Boolean).join(" ")}
          style={{ ...scope.style, ...style }}
          {...props}
        />
      </SurfaceProvider>
    );
  },
);

BeautifulUIPortalRoot.displayName = "BeautifulUIPortalRoot";

export default BeautifulUIRoot;

