"use client";

import { useEffect, useState } from "react";

export function useReducedMotion() {
  const [reduced, setReduced] = useState(false);

  useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(query.matches);
    update();
    query.addEventListener("change", update);
    return () => query.removeEventListener("change", update);
  }, []);

  return reduced;
}

"use client";

import { forwardRef, type ButtonHTMLAttributes } from "react";
import { Button as BoringUIButton } from "@/components/ui/button";

export type ButtonVariant = "primary" | "secondary" | "ghost" | "accent" | "success";
type Size = "sm" | "md";

export interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: ButtonVariant;
  size?: Size;
}

const variantMap = {
  primary: "primary",
  secondary: "secondary",
  ghost: "ghost",
  accent: "primary",
  success: "primary",
} as const;

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(
  ({ variant = "secondary", size = "md", ...props }, ref) => (
    <BoringUIButton ref={ref} variant={variantMap[variant]} size={size} {...props} />
  ),
);

Button.displayName = "Button";
